import os
import boto3

def conditional_update(payload, config=None):
    config = config or {}
    region = os.environ.get("AWS_REGION", "us-east-1") # Specify a default region if not set
    dynamodb = boto3.client('dynamodb', region_name=region)

    table_name = payload["table_name"]
    item_key = payload["key"] # e.g., {"id": "item123"}
    update_data = payload["update_data"] # e.g., {"status": "processed", "description": "task completed"}
    expected_version = payload["expected_version"] # e.g., 1 (for optimistic locking)

    # Convert simple Python key dict to DynamoDB's AttributeValue format
    dynamodb_key = {}
    for k, v in item_key.items():
        if isinstance(v, str):
            dynamodb_key[k] = {'S': v}
        elif isinstance(v, int):
            dynamodb_key[k] = {'N': str(v)}
        elif isinstance(v, float):
            dynamodb_key[k] = {'N': str(v)}
        # Extend for other key types as needed

    update_expression_parts = []
    expression_attribute_names = {}
    expression_attribute_values = {}

    # 1. Increment the version number for optimistic locking
    new_version = expected_version + 1
    update_expression_parts.append("#v = :new_v")
    expression_attribute_names["#v"] = "version" # Assuming 'version' is the name of your version attribute
    expression_attribute_values[":new_v"] = {'N': str(new_version)}

    # 2. Add other attributes from update_data to the expression
    for i, (attr_name, attr_value) in enumerate(update_data.items()):
        name_alias = f"#attr{i}"
        value_alias = f":val{i}"
        update_expression_parts.append(f"{name_alias} = {value_alias}")
        expression_attribute_names[name_alias] = attr_name

        # Convert Python value to DynamoDB AttributeValue format
        if isinstance(attr_value, str):
            expression_attribute_values[value_alias] = {'S': attr_value}
        elif isinstance(attr_value, int):
            expression_attribute_values[value_alias] = {'N': str(attr_value)}
        elif isinstance(attr_value, float):
            expression_attribute_values[value_alias] = {'N': str(attr_value)}
        elif isinstance(attr_value, bool):
            expression_attribute_values[value_alias] = {'BOOL': attr_value}
        elif isinstance(attr_value, list):
            # Simplistic conversion for list of strings; adapt for mixed types
            expression_attribute_values[value_alias] = {'L': [{'S': item} for item in attr_value if isinstance(item, str)]}
        elif isinstance(attr_value, dict):
            # Simplistic conversion for map of strings; adapt for mixed types
            expression_attribute_values[value_alias] = {'M': {k: {'S': v} for k, v in attr_value.items() if isinstance(v, str)}}
        elif attr_value is None:
            expression_attribute_values[value_alias] = {'NULL': True}
        # Add other complex types (sets, binary) as needed

    update_expression = "SET " + ", ".join(update_expression_parts)

    # 3. Define the ConditionExpression for version-aware update
    # The update will only succeed if the 'version' attribute currently matches 'expected_version'
    condition_expression = "#v = :expected_v"
    expression_attribute_values[":expected_v"] = {'N': str(expected_version)}

    result = dynamodb.update_item(
        TableName=table_name,
        Key=dynamodb_key,
        UpdateExpression=update_expression,
        ConditionExpression=condition_expression,
        ExpressionAttributeNames=expression_attribute_names,
        ExpressionAttributeValues=expression_attribute_values,
        ReturnValues="ALL_NEW" # Return the item's attributes after the update
    )
    return result
